(() => {
  const courses = window.COURSES;
  const state = loadState();
  state.lessonWork ||= {};
  state.lessonDrafts ||= {};
  // Old read-only completion marks are intentionally retired: lesson progress now
  // needs proof that the learner edited and successfully ran their own code.
  state.completed = state.completed.filter(key => state.lessonWork[key]?.passed && state.lessonWork[key]?.code === state.lessonDrafts[key]);
  state.projectDone = (state.projectDone || []).filter(key => state.lessonWork['project-' + key]?.passed && state.lessonWork['project-' + key]?.code === state.lessonDrafts['project-' + key]);
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const view = $('#view');
  let toastTimer, searchTerm = '', filterCategory = 'All', filterLevel = 'All';
  function loadState(){try{return Object.assign({completed:[],bookmarks:[],notes:{},quizAnswers:{},quizScores:{},problemSolved:[],projectDone:[],last:{course:'html',stage:0,lesson:0},theme:'light',user:null,localProfiles:[]},JSON.parse(localStorage.getItem('codecraft-state')||'{}'))}catch{return {completed:[],bookmarks:[],notes:{},quizAnswers:{},quizScores:{},problemSolved:[],projectDone:[],last:{course:'html',stage:0,lesson:0},theme:'light',user:null,localProfiles:[]}}}
  function save(){localStorage.setItem('codecraft-state',JSON.stringify(state));renderSide()}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
  function course(id){return courses.find(c=>c.id===id)||courses[0]}
  function lessonList(c){return c.stages.flatMap((s,si)=>s.lessons.map((l,li)=>({...l,stage:si,index:li,stageName:s.name,key:`${c.id}-${si}-${li}`})))}
  function getLesson(c,si,li){return c.stages[si]?.lessons[li]}
  function totalLessons(c){return lessonList(c).length}
  function isDone(key){return state.completed.includes(key)}
  function workPassed(key){const work=state.lessonWork[key],draft=state.lessonDrafts[key];return !!(work?.passed&&draft?.trim()&&work.code===draft)}
  function updateLessonWorkUI(key){const project=key.startsWith('project-'),status=$('[data-work-status="'+key+'"]'),button=project?$('#finishProject'):$('#completeLesson');if(!status||!button)return;const ready=workPassed(key),record=key.replace(/^project-/,'');const done=project?state.projectDone.includes(record):isDone(key);status.textContent=done?'Your changed code ran successfully. Project complete.':ready?'Your edited code ran successfully. You can complete this work.':'Change the starter code, then run it successfully to unlock completion.';status.classList.toggle('ready',ready);button.disabled=!ready||done;}
  function editorProgressKey(ed){if(ed.dataset.editor==='lessonEditor')return state.last.course+'-'+state.last.stage+'-'+state.last.lesson;if(ed.dataset.editor==='projectEditor'&&state.lastProjectKey)return 'project-'+state.lastProjectKey;return ''}
  function editorStarter(ed,original,key){if(key.startsWith('project-')){const index=PROJECTS.findIndex((project,i)=>'project-'+project.course+'-'+i===key);return PROJECTS[index]?.starter||original}return getLesson(course(state.last.course),state.last.stage,state.last.lesson)?.code||original}
  function recordLessonRun(ed,success){const key=editorProgressKey(ed);if(!key)return;const code=$('.code-input',ed).value,starter=editorStarter(ed,code,key);if(success&&code.trim()&&code.trim()!==starter.trim()){state.lessonDrafts[key]=code;state.lessonWork[key]={passed:true,code};}else{delete state.lessonWork[key];state.completed=state.completed.filter(item=>item!==key);state.projectDone=state.projectDone.filter(item=>'project-'+item!==key)}save();updateLessonWorkUI(key)}
  function progress(c){const ls=lessonList(c);return ls.length?Math.round(ls.filter(l=>isDone(l.key)).length/ls.length*100):0}
  function esc(v=''){return String(v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
  function setRoute(hash){location.hash=hash}
  function setActive(route){$$('.primary-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));}
  function renderSide(){const el=$('#sideCourses');el.innerHTML=courses.slice(0,4).map(c=>`<a href="#course/${c.id}" class="side-course"><span class="course-mini ${c.accent}">${esc(c.symbol)}</span><span>${esc(c.short)}</span><span class="side-progress">${progress(c)}%</span></a>`).join('');$('#bookmarkCount').textContent=state.bookmarks.length||'';const user=state.user;$('.profile-mini .avatar').textContent=(user?.name||'L').slice(0,1).toUpperCase();$('.profile-mini strong').textContent=user?.name||'Learner';$('.profile-mini span').textContent=user?'Local profile':'Guest mode';$('#accountLink').textContent=user?'Profile':'Sign in';$('#accountLink').href=user?'#profile':'#auth';}
  function header(crumb,title){$('#breadcrumbs').innerHTML=`<span>Workspace</span><b>/</b><strong>${esc(crumb||title)}</strong>`}
  function progressbar(p){return `<div class="progress-track"><span style="width:${p}%"></span></div>`}
  function courseCard(c){const p=progress(c);return `<article class="course-card" data-course="${c.id}"><a class="course-card-main" href="#course/${c.id}"><div class="course-symbol ${c.accent}">${esc(c.symbol)}</div><span class="pill pill-soft">${esc(c.category)}</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="course-meta"><span>◷ ${esc(c.duration)}</span><span>Beginner · Medium · Intermediate · Advanced</span></div></a><div class="course-card-foot">${progressbar(p)}<span>${p ? `${p}% complete` : 'Start learning'}</span></div></article>`}
  function courseResources(c){return `<section class="course-resources"><div><span class="eyebrow muted">GO DEEPER WITH PRIMARY REFERENCES</span><h2>Trusted learning sources</h2><p>Use these official guides and maintained references alongside the hands-on labs.</p></div><div class="resource-links">${(c.resources||[]).map(([title,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} <span>↗</span></a>`).join('')}</div></section>`}
  function renderHome(){setActive('home');header('Overview','Overview');const active=courses.filter(c=>progress(c)>0);const continueCourse=course(state.last.course||active[0]?.id||'html');const lp=state.last;const next=getLesson(continueCourse,lp.stage,lp.lesson)||lessonList(continueCourse)[0];const finished=state.completed.length;view.innerHTML=`<section class="welcome-row"><div><div class="eyebrow"><span class="eyebrow-dot"></span> YOUR LEARNING SPACE</div><h1>A little progress<br>goes a <em>long way.</em></h1><p class="welcome-copy">Pick a path, follow your curiosity, and build something real. Your next step is ready when you are.</p><div class="welcome-actions"><a class="button button-primary" href="#lesson/${continueCourse.id}/${lp.stage||0}/${lp.lesson||0}">Continue learning <span>→</span></a><a class="button button-quiet" href="#explore">Explore courses <span>↗</span></a></div></div><div class="welcome-illustration"><div class="orbital orbit-a"></div><div class="orbital orbit-b"></div><div class="learn-tile"><span class="tile-symbol">{ }</span><span class="tile-line"></span><span class="tile-line short"></span><span class="tile-dots">···</span></div><span class="float-spark spark-one">✳</span><span class="float-spark spark-two">✦</span><span class="float-note">keep going</span></div></section><section class="stat-grid"><article class="stat-card"><span class="stat-icon lilac">◷</span><span class="stat-label">Study streak</span><strong>${finished?Math.min(finished,7):0} <small>days</small></strong><span class="stat-foot">${finished?'You are building a habit':'Start a learning streak today'}</span></article><article class="stat-card"><span class="stat-icon mint">✓</span><span class="stat-label">Lessons completed</span><strong>${finished}<small>/${courses.reduce((n,c)=>n+totalLessons(c),0)}</small></strong><span class="stat-foot">${finished?'One lesson at a time':'Every small step counts'}</span></article><article class="stat-card"><span class="stat-icon peach">⌘</span><span class="stat-label">Problems solved</span><strong>${state.problemSolved.length}<small> solved</small></strong><span class="stat-foot">Practice builds confidence</span></article><article class="stat-card"><span class="stat-icon sky">✦</span><span class="stat-label">Quiz accuracy</span><strong>${quizAccuracy()}<small>%</small></strong><span class="stat-foot">Across your knowledge checks</span></article></section><section class="section-block"><div class="section-heading"><div><div class="eyebrow muted">PICK UP WHERE YOU LEFT OFF</div><h2>Your learning paths</h2></div><a class="text-link" href="#explore">Browse all courses <span>→</span></a></div><div class="course-grid">${(active.length?active.slice(0,3):courses.slice(0,3)).map(courseCard).join('')}</div></section><section class="continue-banner"><div class="continue-icon ${continueCourse.accent}">${esc(continueCourse.symbol)}</div><div class="continue-copy"><span class="eyebrow muted">A GOOD NEXT STEP</span><h3>${esc(next?.title||continueCourse.title)}</h3><p>${esc(continueCourse.title)} <span>·</span> ${esc(next?.time||'15 min')}</p></div><a href="#lesson/${continueCourse.id}/${lp.stage||0}/${lp.lesson||0}" class="button button-secondary">Continue <span>→</span></a></section>`}
  function quizAccuracy(){const scores=Object.values(state.quizScores);if(!scores.length)return 0;return Math.round(scores.reduce((a,b)=>a+b,0)/scores.length)}
  function renderExplore(){setActive('explore');header('Explore courses','Explore courses');const cats=['All',...new Set(courses.map(c=>c.category))];view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> COURSE LIBRARY</div><h1>Find your next <em>thing.</em></h1><p>Choose a skill, then start at Beginner, Medium, Intermediate, or Advanced. Every route includes editable code labs.</p></div><div class="explore-controls"><label class="search-field"><span>⌕</span><input id="courseSearch" value="${esc(searchTerm)}" placeholder="Try “loops”, “web”, or “Python”" aria-label="Search courses"></label><select id="categoryFilter" aria-label="Filter category">${cats.map(x=>`<option ${x===filterCategory?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="levelFilter" aria-label="Filter level"><option>All levels</option>${['Beginner','Medium','Intermediate','Advanced'].map(level=>`<option ${filterLevel===level?'selected':''}>${level}</option>`).join('')}</select></div><div class="filter-chips">${cats.map(x=>`<button class="filter-chip ${x===filterCategory?'selected':''}" data-category="${esc(x)}">${esc(x)}</button>`).join('')}<span class="results-count" id="resultsCount"></span></div><div class="course-grid explore-grid" id="courseGrid"></div><section class="library-note"><span>✳</span><div><strong>43 learning paths · four entry levels · 100+ editable labs</strong><p>Learn programming languages, web development, app development, databases, algorithms, data and AI, security, systems, cloud, and DevOps. Start at any level and build real projects.</p></div></section>`;const redraw=()=>{searchTerm=$('#courseSearch').value.toLowerCase();filterCategory=$('#categoryFilter').value;filterLevel=$('#levelFilter').value;const filtered=courses.filter(c=>(filterCategory==='All'||c.category===filterCategory)&&(filterLevel==='All levels'||(c.levels||[c.level]).includes(filterLevel))&&`${c.title} ${c.category} ${c.description} ${c.tags.join(' ')} ${lessonList(c).map(l=>l.title).join(' ')}`.toLowerCase().includes(searchTerm));$('#courseGrid').innerHTML=filtered.length?filtered.map(courseCard).join(''):`<div class="empty-state"><span>⌕</span><h3>No paths found</h3><p>Try another search or clear a filter.</p></div>`;$('#resultsCount').textContent=`${filtered.length} course${filtered.length===1?'':'s'}`;};$('#courseSearch').addEventListener('input',redraw);$('#categoryFilter').addEventListener('change',redraw);$('#levelFilter').addEventListener('change',redraw);$$('.filter-chip').forEach(b=>b.addEventListener('click',()=>{$('#categoryFilter').value=b.dataset.category;redraw();$$('.filter-chip').forEach(x=>x.classList.toggle('selected',x===b))}));redraw()}
  function renderCourse(id){const c=course(id);setActive('explore');header('Courses',c.title);const p=progress(c);view.innerHTML=`<a class="back-link" href="#explore">← All courses</a><section class="course-hero"><div><div class="eyebrow"><span class="eyebrow-dot"></span> ${esc(c.category.toUpperCase())} · ${esc(c.level.toUpperCase())}</div><h1>${esc(c.title)}<br><em>from first principles.</em></h1><p>${esc(c.description)}</p><div class="course-hero-meta"><span>◷ ${esc(c.duration)}</span><span>◈ ${totalLessons(c)} lessons</span><span>◎ ${esc(c.level)}</span></div></div><div class="hero-course-art"><div class="hero-course-symbol ${c.accent}">${esc(c.symbol)}</div><span class="art-dot dot-a"></span><span class="art-dot dot-b"></span><span class="art-ring"></span></div></section><section class="course-overview"><div><div class="section-heading compact"><div><div class="eyebrow muted">YOUR ROADMAP</div><h2>A path you can follow</h2></div><span class="overall-progress">${p}% complete</span></div>${progressbar(p)}<div class="level-paths" aria-label="Choose a learning level"><span>Choose your level</span><a href="#lesson/${c.id}/0/0">Beginner</a>${['Medium','Intermediate','Advanced'].map(level=>{const index=c.stages.findIndex(stage=>stage.level===level);return `<a href="#lesson/${c.id}/${index}/0">${level}</a>`}).join('')}</div><div class="roadmap">${c.stages.map((s,si)=>`<article class="roadmap-stage"><div class="stage-marker ${s.lessons.every((l,li)=>isDone(`${c.id}-${si}-${li}`))?'completed':''}">${s.lessons.every((l,li)=>isDone(`${c.id}-${si}-${li}`))?'✓':String(si+1).padStart(2,'0')}</div><div class="stage-content"><div class="stage-title-row"><div><span class="stage-label">STAGE ${String(si+1).padStart(2,'0')}</span><h3>${esc(s.name)}</h3></div><span class="stage-count">${s.lessons.length} lessons</span></div><div class="lesson-list">${s.lessons.map((l,li)=>{const done=isDone(`${c.id}-${si}-${li}`);return `<a class="roadmap-lesson ${done?'done':''}" href="#lesson/${c.id}/${si}/${li}"><span class="lesson-status">${done?'✓':'→'}</span><span>${esc(l.title)}</span><small>${esc(l.time)}</small></a>`}).join('')}</div></div></article>`).join('')}</div></div><aside class="course-aside"><div class="aside-card"><span class="aside-icon">✳</span><h3>Learn by doing</h3><p>Every lesson has an example to explore and a short knowledge check. Go at your own pace.</p><div class="aside-stat"><span>Progress</span><strong>${p}%</strong></div>${progressbar(p)}<a class="button button-primary full" href="#lesson/${c.id}/${state.last.course===c.id?state.last.stage:0}/${state.last.course===c.id?state.last.lesson:0}">${p?'Continue path':'Start this path'} <span>→</span></a></div><div class="aside-card mini-aside"><span class="eyebrow muted">WHAT YOU’LL PRACTICE</span><div class="tag-wrap">${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p>No setup required for the guided lessons.</p></div></aside></section>${courseResources(c)}`}
  function renderLesson(id,si,li){const c=course(id),l=getLesson(c,Number(si),Number(li));if(!l){setRoute(`course/${id}`);return}state.last={course:id,stage:Number(si),lesson:Number(li)};save();setActive('explore');header(c.title,l.title);const all=lessonList(c),idx=all.findIndex(x=>x.key===`${id}-${si}-${li}`),prev=all[idx-1],next=all[idx+1],key=`${id}-${si}-${li}`,done=isDone(key)&&workPassed(key),bookmarked=state.bookmarks.includes(key);view.innerHTML=`<div class="lesson-layout"><aside class="lesson-sidebar"><a class="back-link" href="#course/${c.id}">← ${esc(c.title)}</a><div class="lesson-side-progress"><span>COURSE PROGRESS</span><b>${progress(c)}%</b></div>${progressbar(progress(c))}<div class="lesson-side-list">${c.stages.map((s,sidx)=>`<div class="lesson-group"><span class="lesson-group-title">${esc(s.name)}</span>${s.lessons.map((item,lidx)=>`<a href="#lesson/${c.id}/${sidx}/${lidx}" class="lesson-side-link ${sidx===Number(si)&&lidx===Number(li)?'current':''} ${isDone(`${c.id}-${sidx}-${lidx}`)?'done':''}"><span>${isDone(`${c.id}-${sidx}-${lidx}`)?'✓':'○'}</span>${esc(item.title)}</a>`).join('')}</div>`).join('')}</div></aside><article class="lesson-article"><div class="lesson-overline"><a href="#course/${c.id}">${esc(c.title)}</a><span>/</span>${esc(l.stageName)}</div><div class="lesson-title-row"><div><div class="eyebrow muted">LESSON ${String(idx+1).padStart(2,'0')} <span>·</span> ${esc(l.time)}</div><h1>${esc(l.title)}</h1></div><button id="bookmarkBtn" class="icon-button bookmark-button ${bookmarked?'saved':''}" title="${bookmarked?'Remove bookmark':'Bookmark lesson'}">${bookmarked?'♥':'♡'}</button></div><p class="lesson-intro">${esc(l.intro)}</p><div class="objectives-box"><strong>By the end, you can</strong><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><p><b>Before you begin:</b> ${esc(l.prerequisites)}</p></div><section class="lesson-section"><h2>The idea</h2><p>${esc(l.concept)}</p><div class="tip-box"><span>✳</span><p><strong>A helpful way to think about it</strong><br>Start with the smallest example. Change one thing, run it, and notice what changed.</p></div></section><section class="lesson-section"><div class="section-heading compact"><div><h2>Try the example</h2><p>Edit the code and run it. The preview is sandboxed in your browser.</p></div><span class="editor-language">${esc(l.kind==='javascript'?'JavaScript':l.kind==='html'?'HTML':l.kind==='css'?'CSS':l.kind==='sql'?'SQL':l.kind==='cpp'?'C++':'Python')} · ${['html','css','javascript'].includes(l.kind)?'RUNNABLE':'EXAMPLE'}</span></div>${editor(state.lessonDrafts[key]??l.code,l.kind,`lessonEditor`,l.test||'Edit this example, then press Run.')}</section><section class="lesson-section"><h2>Walk through it</h2><ol class="explanation-list">${l.explanation.map(e=>`<li>${esc(e)}</li>`).join('')}</ol></section><section class="lesson-section mistakes-box"><h2>Common slips</h2>${l.mistakes.map(x=>`<p><span>↗</span>${esc(x)}</p>`).join('')}</section><section class="lesson-section quiz-box"><div class="eyebrow muted">QUICK KNOWLEDGE CHECK</div><h2>${esc(l.check.q)}</h2><div class="quiz-options">${l.check.options.map((o,i)=>`<button class="quiz-option" data-choice="${i}">${esc(o)}</button>`).join('')}</div><div id="quizFeedback" class="quiz-feedback" aria-live="polite"></div><button class="button button-secondary" id="checkAnswer">Check answer <span>→</span></button></section><section class="lesson-section note-box"><label for="lessonNote"><h2>Your notes</h2><span>Saved on this device</span></label><textarea id="lessonNote" placeholder="Write a thought, question, or reminder...">${esc(state.notes[key]||'')}</textarea></section><div class="lesson-end"><a class="text-link" href="#course/${c.id}">Back to roadmap</a><p class="lesson-work-status" data-work-status="${key}" aria-live="polite"></p><button id="completeLesson" disabled class="button ${done?'button-done':'button-primary'}">${done?'✓ Completed':'Mark lesson complete'} ${done?'':'→'}</button></div><div class="lesson-pagination">${prev?`<a href="#lesson/${c.id}/${prev.stage}/${prev.index}"><span>← PREVIOUS</span><strong>${esc(prev.title)}</strong></a>`:'<span></span>'}${next?`<a class="next-lesson" href="#lesson/${c.id}/${next.stage}/${next.index}"><span>NEXT LESSON →</span><strong>${esc(next.title)}</strong></a>`:`<a class="next-lesson" href="#course/${c.id}"><span>ROADMAP →</span><strong>Review your path</strong></a>`}</div></article></div>`;
    let chosen=null;$$('.quiz-option').forEach(b=>b.addEventListener('click',()=>{$$('.quiz-option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');chosen=Number(b.dataset.choice)}));$('#checkAnswer').onclick=()=>{if(chosen===null){toast('Choose an answer first.');return}const ok=chosen===l.check.answer;state.quizAnswers[key]=chosen;state.quizScores[key]=ok?100:0;save();$('#quizFeedback').className=`quiz-feedback visible ${ok?'correct':'incorrect'}`;$('#quizFeedback').innerHTML=`<strong>${ok?'That’s right!':'Not quite yet.'}</strong> ${esc(l.check.why)}`};if(state.quizAnswers[key]!==undefined){chosen=state.quizAnswers[key];$$('.quiz-option')[chosen]?.classList.add('selected');$('#quizFeedback').className=`quiz-feedback visible ${chosen===l.check.answer?'correct':'incorrect'}`;$('#quizFeedback').innerHTML=`<strong>${chosen===l.check.answer?'That’s right!':'Not quite yet.'}</strong> ${esc(l.check.why)}`}
    $('#completeLesson').onclick=()=>{if(!isDone(key))state.completed.push(key);save();toast('Lesson marked complete. Nice work!');renderLesson(id,si,li)};
    $('#bookmarkBtn').onclick=()=>{if(state.bookmarks.includes(key))state.bookmarks=state.bookmarks.filter(x=>x!==key);else state.bookmarks.push(key);save();renderLesson(id,si,li);toast(state.bookmarks.includes(key)?'Lesson saved to bookmarks.':'Bookmark removed.')};
    $('#lessonNote').addEventListener('input',e=>{state.notes[key]=e.target.value;save()});setupEditor();updateLessonWorkUI(key);$("#completeLesson").addEventListener("click",event=>{if(!workPassed(key)){event.stopImmediatePropagation();toast("Edit the code and run it successfully before completing this lesson.")}},true);
  }
  function editor(code,kind,id,expected){const runnable=['html','css','javascript'].includes(kind)||!!runnerLanguage(kind);return `<div class="editor" data-editor="${id}" data-kind="${kind}"><div class="editor-bar"><div><span class="editor-dot red"></span><span class="editor-dot yellow"></span><span class="editor-dot green-dot"></span><span class="editor-file">${kind==='html'?'index.html':kind==='css'?'styles.css':kind==='sql'?'query.sql':kind==='cpp'?'main.cpp':kind==='python'?'main.py':'script.js'}</span></div><button class="copy-code" data-copy="${id}">▢ Copy</button></div><textarea class="code-input" spellcheck="false" aria-label="Code editor">${esc(code)}</textarea><div class="editor-controls">${runnable?`<button class="button button-primary run-code" data-run="${id}">▶ Run code</button>`:'<button class="button button-quiet" disabled>Explanation only</button>'}<button class="button button-quiet reset-code" data-reset="${id}">↺ Reset</button><span class="run-note">${['html','css','javascript'].includes(kind)?'Runs in a sandboxed browser preview':runnerLanguage(kind)?'Runs through your configured isolated runner':'Reference snippet · no executable program'}</span></div><div class="output-wrap"><div class="output-head"><span>OUTPUT</span><button class="output-tab active" data-output-tab="console">Console</button><button class="output-tab" data-output-tab="preview">Preview</button><button class="compare-toggle" data-compare="${id}">Compare expected</button></div><pre class="output-console">${esc(expected)}</pre><iframe class="output-preview" title="Sandboxed code preview" sandbox="allow-scripts" hidden></iframe><div class="compare-result" hidden></div></div></div>`}
  function setupEditor(){ $$('.editor').forEach(ed=>{const ta=$(".code-input",ed),original=ta.value,key=editorProgressKey(ed),starter=key?editorStarter(ed,original,key):original,kind=ed.dataset.kind;ta.addEventListener("input",()=>{const key=editorProgressKey(ed);if(!key)return;state.lessonDrafts[key]=ta.value;if(ta.value.trim()===starter.trim())delete state.lessonDrafts[key];if(state.lessonWork[key]?.code!==ta.value){delete state.lessonWork[key];state.completed=state.completed.filter(item=>item!==key);state.projectDone=state.projectDone.filter(item=>"project-"+item!==key)}$(".output-console",ed).classList.remove("has-error");$(".error-help",ed)?.setAttribute("hidden","");save();updateLessonWorkUI(key)});$$('[data-copy]',ed).forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(ta.value);toast('Code copied.')}catch{ta.select();document.execCommand('copy');toast('Code copied.')}});$('[data-reset]',ed).onclick=()=>{ta.value=starter;ta.dispatchEvent(new Event("input"));toast("Starter restored. Make your own change before completing.")};$('[data-run]',ed).onclick=async()=>{const code=ta.value,task=runEditor(ed);await task;if(kind==="html"||kind==="css"||(kind==="javascript"&&$(".output-console",ed).textContent==="Running…"))await new Promise(resolve=>setTimeout(resolve,100));recordLessonRun(ed,ta.value===code&&!$(".output-console",ed).classList.contains("has-error")&&(kind!=="javascript"||$(".output-console",ed).textContent!=="Running…"))};$$('[data-output-tab]',ed).forEach(b=>b.onclick=()=>{ $$('[data-output-tab]',ed).forEach(x=>x.classList.toggle('active',x===b));$('.output-console',ed).hidden=b.dataset.outputTab!=='console';$('.output-preview',ed).hidden=b.dataset.outputTab!=='preview';});$('[data-compare]',ed).onclick=()=>{const result=$('.compare-result',ed),consoleEl=$('.output-console',ed);result.hidden=!result.hidden;if(!result.hidden)result.innerHTML=`<span class="compare-label">EXPECTED</span><pre>${esc(consoleEl.textContent)}</pre>`};}) }
  function runEditor(ed){const kind=ed.dataset.kind,code=$('.code-input',ed).value,out=$('.output-console',ed),frame=$('.output-preview',ed);if(kind==='html'){frame.hidden=false;out.hidden=true;$$('[data-output-tab]',ed).forEach(b=>b.classList.toggle('active',b.dataset.outputTab==='preview'));frame.srcdoc=code;return}if(kind==='css'){frame.hidden=false;out.hidden=true;$$('[data-output-tab]',ed).forEach(b=>b.classList.toggle('active',b.dataset.outputTab==='preview'));frame.srcdoc=`<!doctype html><html><head><style>body{font:16px system-ui;padding:24px;color:#334;background:#fff}${code}</style></head><body><h1>CSS preview</h1><p>Edit the styles to see the page change.</p><button>A sample button</button></body></html>`;return}if(kind==='javascript'){frame.hidden=true;out.hidden=false;$$('[data-output-tab]',ed).forEach(b=>b.classList.toggle('active',b.dataset.outputTab==='console'));const safeCode=code.replace(/<\/script/gi,'<\\/script');frame.srcdoc=`<!doctype html><meta charset="utf-8"><script>const logs=[];console.log=(...args)=>logs.push(args.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(' '));console.error=(...args)=>logs.push('Error: '+args.join(' '));window.onerror=(m,s,l,c)=>{logs.push('Error: '+m+' (line '+l+')');document.querySelector('#output').textContent=logs.join('\\n')};try{${safeCode}}catch(e){logs.push(e.name+': '+e.message)}parent.postMessage({type:'codecraft-output',logs},'*');<\/script><pre id="output"></pre>`;out.textContent='Running…';const listener=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='codecraft-output')return;out.textContent=e.data.logs.join('\n')||'(No output — try adding console.log(...))';window.removeEventListener('message',listener)};window.addEventListener('message',listener);setTimeout(()=>window.removeEventListener('message',listener),3000);return}toast(`${kind.toUpperCase()} is shown as an example here; execution is not enabled.`)}
  function renderPractice(){setActive('practice');header('Practice arena','Practice arena');view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> PRACTICE ARENA</div><h1>Build skill by <em>trying.</em></h1><p>Short, focused challenges. Take your time—attempts are for learning.</p></div><div class="practice-toolbar"><div class="filter-chips"><button class="filter-chip selected" data-problem-filter="All">All challenges</button>${['Beginner','Easy'].map(x=>`<button class="filter-chip" data-problem-filter="${x}">${x}</button>`).join('')}</div><span class="results-count">${state.problemSolved.length} solved</span></div><div class="practice-list">${PROBLEMS.map((p,i)=>`<article class="problem-card"><div class="problem-number">${String(i+1).padStart(2,'0')}</div><div class="problem-main"><div class="problem-tags"><span class="difficulty">${p.difficulty}</span><span>${esc(course(p.course).short)}</span><span>${esc(p.topic)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.prompt)}</p><button class="text-link open-problem" data-problem="${p.id}">${state.problemSolved.includes(p.id)?'Solved ✓ · Review':'Open challenge'} <span>→</span></button></div><span class="problem-status ${state.problemSolved.includes(p.id)?'solved':''}">${state.problemSolved.includes(p.id)?'✓':'○'}</span></article>`).join('')}</div>`;$$('[data-problem-filter]').forEach(b=>b.onclick=()=>{const f=b.dataset.problemFilter;$$('[data-problem-filter]').forEach(x=>x.classList.toggle('selected',x===b));$$('.problem-card').forEach(card=>{const p=PROBLEMS.find(x=>x.id===card.querySelector('[data-problem]').dataset.problem);card.hidden=f!=='All'&&p.difficulty!==f})});$$('[data-problem]').forEach(b=>b.onclick=()=>renderProblem(b.dataset.problem))}
  function renderProblem(id){const p=PROBLEMS.find(x=>x.id===id);if(!p)return;header('Practice arena',p.title);view.innerHTML=`<a class="back-link" href="#practice">← Practice arena</a><div class="problem-workspace"><article class="problem-instructions"><div class="problem-tags"><span class="difficulty">${p.difficulty}</span><span>${esc(course(p.course).title)}</span><span>${esc(p.topic)}</span></div><h1>${esc(p.title)}</h1><p>${esc(p.prompt)}</p><div class="sample-box"><span>EXAMPLE</span><pre>${esc(p.starter)}</pre></div><div class="hint-stack"><h3>Need a nudge?</h3><p>Hints reveal one step at a time. Try thinking before you open the next one.</p><div id="hints"></div><button class="button button-quiet" id="showHint">Show next hint <span>→</span></button><button class="text-link" id="revealSolution">I’m ready to see the solution</button><div id="solution" hidden><h3>One possible solution</h3><pre class="solution-code">${esc(p.solution)}</pre><p>${esc(p.explanation)}</p></div></div></article><section class="problem-editor-pane"><div class="eyebrow muted">YOUR SOLUTION</div>${editor(p.starter,p.course==='javascript'?'javascript':p.course==='sql'?'sql':p.course==='cpp'?'cpp':'python','problemEditor',p.expected)}<button id="submitProblem" class="button button-primary submit-problem">Submit answer <span>→</span></button><div id="submitFeedback" class="submit-feedback" aria-live="polite"></div></section></div>`;let hint=0;$('#showHint').onclick=()=>{if(hint<p.hint.length){$('#hints').insertAdjacentHTML('beforeend',`<div class="hint-item"><span>HINT ${hint+1}</span><p>${esc(p.hint[hint])}</p></div>`);hint++}if(hint===p.hint.length)$('#showHint').textContent='All hints shown'};$('#revealSolution').onclick=()=>{$('#solution').hidden=false;$('#revealSolution').hidden=true};setupEditor();$('#submitProblem').onclick=()=>{const value=$('.code-input').value.trim();const ok=value.includes(p.expected.replace(/\n/g,'').trim().slice(0,22))||value.includes(p.solution.trim().split('\n').find(x=>x.trim()&&!x.includes('#include')&&!x.includes('function')&&!x.startsWith('def'))?.trim()||'***impossible***');const fb=$('#submitFeedback');fb.className=`submit-feedback visible ${ok?'correct':'incorrect'}`;fb.innerHTML=ok?'<strong>Good work!</strong> Your solution includes the key step. Keep going.':'<strong>Not there yet.</strong> Re-read the prompt and try a small example. Your attempts are unlimited.';if(ok&&!state.problemSolved.includes(id)){state.problemSolved.push(id);save()}}}
  function runnerLanguage(kind){return ({typescript:'typescript',c:'c',cpp:'c++',java:'java',csharp:'csharp',php:'php',go:'go',rust:'rust',kotlin:'kotlin',swift:'swift',ruby:'ruby',python:'python',sql:'sqlite3',sqlite:'sqlite3',nodejs:'javascript',bash:'bash'})[kind]||null}
  async function showRuntimeInstall(ed,language,api){const message=`${language} is not installed on this local runner. You can install it from the runner's available package list.`;renderRunError(ed,message,'Runtime');const panel=$('.error-help',ed);const button=document.createElement('button');button.className='install-runtime';button.textContent=`Install ${language} runtime`;panel.querySelector('.fix-actions').prepend(button);button.onclick=async()=>{button.disabled=true;button.textContent='Finding runtime…';try{const listResponse=await fetch(`${api}/packages`);if(!listResponse.ok)throw new Error(`Could not list runner packages (${listResponse.status}).`);const packages=await listResponse.json();const found=(Array.isArray(packages)?packages:[]).filter(p=>p.language===language).sort((a,b)=>String(b.version).localeCompare(String(a.version),undefined,{numeric:true}));const pkg=found.find(p=>!p.installed)||found[0];if(!pkg)throw new Error(`No ${language} package is available in this Piston instance.`);if(pkg.installed){toast(`${language} is installed. Running code…`);return runEditor(ed)}button.textContent=`Installing ${language}…`;const response=await fetch(`${api}/packages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language:pkg.language,version:pkg.version})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.message||`Runtime install failed (${response.status}).`);toast(`${language} runtime installed. Running code…`);return runEditor(ed)}catch(error){renderRunError(ed,`${error.message}\n\nCheck that Docker and the local Piston service are running, then try again.`,'Runtime install')}finally{if(button.isConnected){button.disabled=false;button.textContent=`Install ${language} runtime`}}}}
  function diagnoseError(message,kind){const m=String(message||'Runtime error');const hints=[];if(/Unexpected token|SyntaxError/i.test(m)){hints.push('Check the line named in the error for a missing bracket, quote, comma, or semicolon.','Compare opening and closing parentheses, braces, and brackets.')}if(/ReferenceError|not defined|undefined variable/i.test(m)){hints.push('Check spelling and capitalization of the variable name.','Make sure the variable is declared before this line and is in scope.')}if(/TypeError|null|undefined/i.test(m)){hints.push('Check whether this value exists before using a property or method on it.','Inspect the value’s type and handle empty or missing input.')}if(/IndentationError|expected an indented block/i.test(m)){hints.push('Python uses consistent indentation (usually four spaces) to mark code blocks.')}if(/expected .*;|expected .*\}/i.test(m)){hints.push('Check the compiler location for a missing semicolon or closing brace.')}if(!hints.length)hints.push(`Read the ${kind} error location, inspect the nearby value, then make one change and run again.`);return hints}
  function renderRunError(ed,message,kind){recordLessonRun(ed,false);const out=$('.output-console',ed);out.textContent=message;out.classList.add('has-error');let panel=$('.error-help',ed);if(!panel){panel=document.createElement('div');panel.className='error-help';$('.output-wrap',ed).append(panel)}const fixes=diagnoseError(message,kind);panel.hidden=false;panel.innerHTML=`<strong>⚠ Error · Suggested fixes</strong><ul>${fixes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="fix-actions"><button class="copy-error">Copy error</button><button class="close-error">Dismiss</button></div>`;$('.copy-error',panel).onclick=()=>navigator.clipboard?.writeText(message).then(()=>toast('Error copied.')).catch(()=>toast(message));$('.close-error',panel).onclick=()=>{panel.hidden=true};}
  async function runEditor(ed){const kind=ed.dataset.kind,code=$('.code-input',ed).value,out=$('.output-console',ed),frame=$('.output-preview',ed);out.classList.remove('has-error');$('.error-help',ed)?.setAttribute('hidden','');if(kind==='html'){frame.hidden=false;out.hidden=true;$$('[data-output-tab]',ed).forEach(b=>b.classList.toggle('active',b.dataset.outputTab==='preview'));frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data: https:;">${code}`;return}if(kind==='css'){frame.hidden=false;out.hidden=true;$$('[data-output-tab]',ed).forEach(b=>b.classList.toggle('active',b.dataset.outputTab==='preview'));frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline';"><style>body{font:16px system-ui;padding:24px;color:#334;background:#fff}${code}</style><h1>CSS preview</h1><p>Edit the styles to see the page change.</p><button>A sample button</button>`;return}if(kind==='javascript'){frame.hidden=true;out.hidden=false;$$('[data-output-tab]',ed).forEach(b=>b.classList.toggle('active',b.dataset.outputTab==='console'));const safeCode=code.replace(/<\/script/gi,'<\\/script');frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; connect-src 'none'; img-src data:; style-src 'unsafe-inline';"><script>const logs=[];let failed=false;console.log=(...args)=>logs.push({text:args.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(' ')});console.error=(...args)=>{failed=true;logs.push({text:'Error: '+args.join(' '),error:true})};window.onerror=(m,s,l)=>{failed=true;logs.push({text:'Syntax/runtime error: '+m+' (line '+l+')',error:true});parent.postMessage({type:'codecraft-output',logs,failed},'*')};try{${safeCode}}catch(e){failed=true;logs.push({text:e.name+': '+e.message,error:true})}parent.postMessage({type:'codecraft-output',logs,failed},'*');<\/script>`;out.textContent='Running…';const listener=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='codecraft-output')return;const data=e.data;out.textContent=data.logs.map(x=>x.text).join('\n')||'(No output — add console.log(...) to inspect a value.)';if(data.failed)renderRunError(ed,data.logs.find(x=>x.error)?.text||'Syntax error',kind);window.removeEventListener('message',listener)};window.addEventListener('message',listener);setTimeout(()=>{window.removeEventListener('message',listener);if(out.textContent==='Running…')renderRunError(ed,'Code did not finish. Check for an infinite loop or long-running operation.','JavaScript')},4000);return}
    const language=runnerLanguage(kind);if(!language){renderRunError(ed,`${kind} does not have a runnable runtime configured. Choose a supported language or configure the isolated runner in Code Studio.`,'Runtime');return}const api=(state.executionApi||'/runner/v2').replace(/\/$/,'');out.hidden=false;frame.hidden=true;out.textContent='Compiling and running…';try{if(!state.allowRemoteCode){renderRunError(ed,'External execution is off. In Code Studio, enable “Send code to my configured runner” before running compiled languages.','Runner permission');return}const runtimeRes=await fetch(`${api}/runtimes`);if(!runtimeRes.ok)throw new Error(`Runner unavailable (${runtimeRes.status}). Start your isolated Piston runner or set its API URL in Code Studio.`);const runtimes=await runtimeRes.json();const rt=runtimes.find(r=>r.language===language||r.aliases?.includes(language));if(!rt){showRuntimeInstall(ed,language,api);return}const filename=({c:'main.c','c++':'main.cpp',java:'Main.java',csharp:'main.cs',php:'main.php',python:'main.py',ruby:'main.rb',javascript:'main.js',typescript:'main.ts',sqlite3:'query.sql'})[language]||`main.${language}`;const result=await fetch(`${api}/execute`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language,version:rt.version,files:[{name:filename,content:code}],stdin:'',compile_timeout:10000,run_timeout:3000})});const data=await result.json();const compile=data.compile?.output||'';const output=data.run?.output||data.message||'(Program completed with no output.)';if(!result.ok||data.compile?.code!==0&&data.compile||data.run?.code!==0){renderRunError(ed,[compile,output].filter(Boolean).join('\n'),'Compiler/runtime');return}out.textContent=output;out.classList.remove('has-error')}catch(err){renderRunError(ed,`${err.message}\n\nFix options:\n• Confirm the isolated runner is running and its API URL is correct.\n• Check that the selected runtime is installed.\n• Run this app from localhost or HTTPS so browser security permits the runner connection.`,'Runner')}
  }
  function renderPractice(){setActive('practice');header('Practice arena','Practice arena');view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> PRACTICE ARENA</div><h1>Build skill by <em>trying.</em></h1><p>Study a short concept, run code right here, then try a focused challenge.</p></div><div class="practice-tabs"><a class="practice-tab active" href="#practice">Problem solving</a><a class="practice-tab" href="#practice/studio">Code Studio <span>↗</span></a></div><section class="studio-callout"><div><span class="eyebrow muted">LEARN AND RUN IN ONE PLACE</span><h2>Open the Code Studio</h2><p>Write, run, and debug your code without leaving the learning workspace.</p></div><a class="button button-primary" href="#practice/studio">Open Code Studio <span>→</span></a></section><div class="practice-toolbar"><div class="filter-chips"><button class="filter-chip selected" data-problem-filter="All">All challenges</button>${['Beginner','Easy'].map(x=>`<button class="filter-chip" data-problem-filter="${x}">${x}</button>`).join('')}</div><span class="results-count">${state.problemSolved.length} solved</span></div><div class="practice-list">${PROBLEMS.map((p,i)=>`<article class="problem-card"><div class="problem-number">${String(i+1).padStart(2,'0')}</div><div class="problem-main"><div class="problem-tags"><span class="difficulty">${p.difficulty}</span><span>${esc(course(p.course).short)}</span><span>${esc(p.topic)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.prompt)}</p><button class="text-link open-problem" data-problem="${p.id}">${state.problemSolved.includes(p.id)?'Solved ✓ · Review':'Open challenge'} <span>→</span></button></div><span class="problem-status ${state.problemSolved.includes(p.id)?'solved':''}">${state.problemSolved.includes(p.id)?'✓':'○'}</span></article>`).join('')}</div>`;$$('[data-problem-filter]').forEach(b=>b.onclick=()=>{const f=b.dataset.problemFilter;$$('[data-problem-filter]').forEach(x=>x.classList.toggle('selected',x===b));$$('.problem-card').forEach(card=>{const p=PROBLEMS.find(x=>x.id===card.querySelector('[data-problem]').dataset.problem);card.hidden=f!=='All'&&p.difficulty!==f})});$$('[data-problem]').forEach(b=>b.onclick=()=>renderProblem(b.dataset.problem))}
  function renderStudio(){setActive('practice');header('Practice arena','Code Studio');view.innerHTML=`<a class="back-link" href="#practice">← Problem solving</a><div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> CODE STUDIO · JAVASCRIPT</div><h1>Learn it. Run it. <em>Right here.</em></h1><p>Experiment with JavaScript in this workspace. Run code and inspect output without closing or switching tabs.</p></div><div class="practice-tabs"><a class="practice-tab" href="#practice">Problem solving</a><a class="practice-tab active" href="#practice/studio">Code Studio</a></div><div class="studio-layout"><section class="studio-guide"><span class="eyebrow muted">QUICK LESSON</span><h2>Values, variables, and output</h2><p>A variable gives a value a useful name. Use <code>const</code> when the name won’t be reassigned, and <code>console.log</code> to inspect a result.</p><div class="studio-example"><strong>Try this:</strong><ol><li>Change the learner name.</li><li>Change the minutes studied.</li><li>Press <b>Run code</b> and read the output below.</li></ol></div><a class="text-link" href="#lesson/javascript/0/0">Read the full JavaScript lesson <span>→</span></a><div class="runtime-note"><span>✓</span><p><strong>Runs in your browser</strong><br>JavaScript uses a sandboxed frame. No server upload is needed. Python, C++, and SQL need an isolated runner, so they remain examples for now.</p></div></section><section class="studio-editor"><div class="section-heading compact"><div><div class="eyebrow muted">YOUR PLAYGROUND</div><h2>Make a change and run</h2></div><span class="editor-language">JavaScript · RUNNABLE</span></div>${editor('const learner = "Sam";\nconst minutesStudied = 25;\n\nconsole.log(`Hello, ${learner}!`);\nconsole.log(`You studied ${minutesStudied} minutes.`);\nconsole.log(`At 5 minutes per break, try ${Math.floor(minutesStudied / 5)} short practice blocks.`);','javascript','studioEditor','Hello, Sam!\nYou studied 25 minutes.\nAt 5 minutes per break, try 5 short practice blocks.')}</section></div><section class="studio-next"><span class="eyebrow muted">READY FOR A CHALLENGE?</span><p>Use what you just practiced in a short coding problem. Your studio code stays on this page until you navigate away.</p><a class="button button-secondary" href="#practice">Choose a problem <span>→</span></a></section>`;setupEditor()}
  function renderAuth(mode='signin'){header('Account','Sign in');const creating=mode==='create';view.innerHTML=`<div class="auth-wrap"><section class="auth-card"><div class="eyebrow"><span class="eyebrow-dot"></span> YOUR CODECRAFT PROFILE</div><h1>${creating?'Create a local profile':'Welcome back'}</h1><p class="auth-lead">${creating?'Save a learner name and email on this device.':'Open a local learner profile saved on this device.'}</p><div class="auth-tabs"><button class="auth-tab ${!creating?'active':''}" data-auth="signin">Sign in</button><button class="auth-tab ${creating?'active':''}" data-auth="create">Create profile</button></div><form id="authForm">${creating?'<label class="form-label">Your name<input id="authName" required maxlength="40" autocomplete="name" placeholder="e.g. Alex"></label>':''}<label class="form-label">Email address<input id="authEmail" required type="email" autocomplete="email" placeholder="you@example.com"></label><p class="auth-hint">This starter uses a device-only profile. It does not ask for or store a password.</p><button class="button button-primary full" type="submit">${creating?'Create local profile':'Continue'} <span>→</span></button></form><button id="guestContinue" class="button button-quiet full">Continue as guest</button><div class="settings-note auth-note"><span>◈</span><p><strong>About sign-in:</strong> This version has no authentication server. Profiles are stored only in this browser and do not sync across devices. A secure backend is required for real password sign-in and recovery.</p></div></section><div class="auth-art"><span> { } </span><p>Your progress,<br>one good step at a time.</p></div></div>`;$$('[data-auth]').forEach(b=>b.onclick=()=>renderAuth(b.dataset.auth));$('#guestContinue').onclick=()=>setRoute('home');$('#authForm').onsubmit=e=>{e.preventDefault();const email=$('#authEmail').value.trim().toLowerCase();let profile;if(creating){const name=$('#authName').value.trim();if(!name||!email)return;profile={name,email};state.localProfiles=[...(state.localProfiles||[]).filter(x=>x.email!==email),profile]}else{profile=(state.localProfiles||[]).find(x=>x.email===email);if(!profile){toast('No local profile found for that email. Choose Create profile first.');return}}state.user=profile;save();toast(creating?'Local profile created.':'Welcome back.');setRoute('profile')};}
  function renderStudio(){setActive('practice');header('Practice arena','Code Studio');const selected=course(state.studioCourse||'javascript');const lesson=getLesson(selected,0,0)||lessonList(selected)[0];const kind=lesson.kind;const runnable=['html','css','javascript'].includes(kind)||!!runnerLanguage(kind);view.innerHTML=`<a class="back-link" href="#practice">← Problem solving</a><div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> CODE STUDIO · LIVE WORKSPACE</div><h1>Learn it. Run it. <em>Right here.</em></h1><p>Pick a learning track, change the sample, and run or preview it in this workspace.</p></div><div class="practice-tabs"><a class="practice-tab" href="#practice">Problem solving</a><a class="practice-tab active" href="#practice/studio">Code Studio</a></div><div class="studio-picker"><label>Learning track<select id="studioCourse">${courses.map(c=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Isolated runner API<input id="runnerEndpoint" value="${esc(state.executionApi||'/runner/v2')}" spellcheck="false"></label><label class="runner-consent"><input id="runnerConsent" type="checkbox" ${state.allowRemoteCode?'checked':''}> Send code to my configured runner for execution</label><p>HTML/CSS/JavaScript examples run in the browser. Other languages need an isolated Piston runner that you control; this app sends code only after you check the box.</p></div><div class="studio-layout"><section class="studio-guide"><span class="eyebrow muted">QUICK LESSON</span><h2>${esc(lesson.title)}</h2><p>${esc(lesson.concept)}</p><div class="studio-example"><strong>Try this:</strong><ol><li>Change one value in the sample.</li><li>Press <b>Run code</b> and inspect output.</li><li>If there is an error, use the red diagnostics below the console.</li></ol></div><a class="text-link" href="#lesson/${selected.id}/0/0">Open this full lesson <span>→</span></a><div class="runtime-note"><span>✓</span><p><strong>${runnable?'Runnable learning sample':'Explanation sample'}</strong><br>${runnable?`${esc(kind.toUpperCase())} is selected. Compiled languages run through your configured isolated runner.`:'This lesson contains a diagram or explanatory snippet, not executable source code. Choose a programming-language course to run code.'}</p></div></section><section class="studio-editor"><div class="section-heading compact"><div><div class="eyebrow muted">YOUR PLAYGROUND</div><h2>${esc(selected.title)}</h2></div><span class="editor-language">${esc(kind.toUpperCase())} · ${runnable?'RUN':'REFERENCE'}</span></div>${editor(lesson.code,kind,'studioEditor',lesson.test||'Run the example and inspect the output.')}</section></div><section class="studio-next"><span class="eyebrow muted">READY FOR A CHALLENGE?</span><p>Try a problem from the practice arena or keep learning through the course roadmap.</p><a class="button button-secondary" href="#practice">Choose a problem <span>→</span></a><a class="text-link" href="#course/${selected.id}">View roadmap →</a></section>`;$('#studioCourse').onchange=e=>{state.studioCourse=e.target.value;save();renderStudio()};$('#runnerEndpoint').onchange=e=>{state.executionApi=e.target.value.trim().replace(/\/$/,'');save();toast('Runner address saved on this device.')};$('#runnerConsent').onchange=e=>{state.allowRemoteCode=e.target.checked;save()};setupEditor()}
  function renderProjects(){setActive('projects');header('Projects','Projects');view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> PROJECT STUDIO</div><h1>Make something <em>yours.</em></h1><p>Guided projects turn concepts into work you can show someone.</p></div><div class="project-grid">${PROJECTS.map((p,i)=>{const c=course(p.course),key=p.course+'-'+i;return `<article class="project-card"><div class="project-art ${c.accent}"><span>${esc(c.symbol)}</span><i>✳</i><b>0${i+1}</b></div><div class="project-card-body"><div class="problem-tags"><span class="difficulty">${esc(p.level)}</span><span>${esc(c.short)}</span><span>◷ ${esc(p.time)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="tag-wrap">${p.skills.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><button class="button ${state.projectDone.includes(key)?'button-done':'button-secondary'} full open-project" data-project="${i}">${state.projectDone.includes(key)?'✓ Completed':'View project guide'} <span>→</span></button></div></article>`}).join('')}</div>`;$$('[data-project]').forEach(b=>b.onclick=()=>renderProject(Number(b.dataset.project)))}
  function renderProject(i){const p=PROJECTS[i],c=course(p.course),key=p.course+'-'+i;state.lastProjectKey=key;header('Projects',p.title);view.innerHTML=`<a class="back-link" href="#projects">← Project studio</a><div class="project-workspace"><article class="project-guide"><div class="eyebrow"><span class="eyebrow-dot"></span> ${esc(p.level.toUpperCase())} PROJECT · ${esc(p.time)}</div><h1>${esc(p.title)}</h1><p class="lesson-intro">${esc(p.description)}</p><h2>What you’ll practice</h2><div class="tag-wrap">${p.skills.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><h2>Milestones</h2><ol class="milestone-list">${p.milestones.map((m,j)=>`<li><span>${String(j+1).padStart(2,'0')}</span>${esc(m)}</li>`).join('')}</ol><div class="tip-box"><span>✳</span><p><strong>Optional stretch goal</strong><br>${esc(p.challenge)}</p></div><h2>Completion checklist</h2><label class="checklist-item"><input type="checkbox" id="projectCheck" ${state.projectDone.includes(key)?'checked':''}> I can explain the main ideas I used and have made at least one change of my own.</label><p id="projectWorkStatus" data-work-status="project-${key}" class="lesson-work-status" aria-live="polite"></p><button id="finishProject" disabled class="button button-primary">${state.projectDone.includes(key)?'Completed ✓':'Mark project complete →'}</button></article><div class="project-editor"><div class="section-heading compact"><div><div class="eyebrow muted">STARTER FILE</div><h2>Start building</h2></div></div>${editor(state.lessonDrafts['project-'+key]??p.starter,p.kind||p.course,'projectEditor','Run or preview your starter file.')}</div></div>`;setupEditor();updateLessonWorkUI("project-"+key);$('#finishProject').onclick=()=>{if($('#projectCheck').checked){if(!state.projectDone.includes(key))state.projectDone.push(key);save();toast('Project milestone saved. Great work!');renderProject(i)}else toast('Complete your checklist before saving progress.') }}
  function renderBookmarks(){setActive('bookmarks');header('Bookmarks and notes','Bookmarks and notes');const items=state.bookmarks.map(k=>{const [id,si,li]=k.split('-'),c=course(id),l=getLesson(c,+si,+li);return l?{k,c,l,note:state.notes[k]||''}:null}).filter(Boolean);view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> YOUR LIBRARY</div><h1>Saved for <em>later.</em></h1><p>Bookmarks and lesson notes stay on this device while you learn as a guest.</p></div>${items.length?`<div class="saved-list">${items.map(x=>`<article class="saved-card"><span class="saved-heart">♥</span><div><span class="eyebrow muted">${esc(x.c.title)}</span><h3><a href="#lesson/${x.k.replaceAll('-','/')}">${esc(x.l.title)}</a></h3><p>${esc(x.note||'No note yet. Open the lesson to add a note.')}</p></div><a href="#lesson/${x.k.replaceAll('-','/')}" class="text-link">Open <span>→</span></a></article>`).join('')}</div>`:`<div class="empty-state"><span>♡</span><h3>Your shelf is waiting</h3><p>Bookmark a lesson with the heart icon and it will show up here.</p><a class="button button-primary" href="#explore">Explore courses <span>→</span></a></div>`}`}
  function renderDashboard(){setActive('home');header('Your progress','Your progress');const active=courses.filter(c=>progress(c)>0),total=courses.reduce((n,c)=>n+totalLessons(c),0),pct=total?Math.round(state.completed.length/total*100):0;view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> YOUR PROGRESS</div><h1>Look how far you’ve <em>come.</em></h1><p>Your learning history is saved locally on this device.</p></div><section class="dashboard-summary"><div class="summary-main"><span class="eyebrow muted">OVERALL LEARNING PROGRESS</span><strong>${pct}<small>%</small></strong>${progressbar(pct)}<span>${state.completed.length} lessons completed across ${active.length} active paths</span></div><div class="summary-secondary"><span class="stat-icon lilac">✦</span><span class="stat-label">Knowledge checks</span><strong>${Object.keys(state.quizScores).length}</strong><span class="stat-foot">${quizAccuracy()}% average accuracy</span></div></section><section class="section-block"><div class="section-heading"><div><div class="eyebrow muted">YOUR PATHS</div><h2>Courses in progress</h2></div><a class="text-link" href="#explore">Explore courses →</a></div><div class="course-grid">${(active.length?active:courses.slice(0,3)).map(courseCard).join('')}</div></section><section class="activity-card"><div class="eyebrow muted">RECENT ACTIVITY</div><h2>A steady practice</h2><div class="activity-list">${state.completed.slice(-5).reverse().map(k=>{const [id,si,li]=k.split('-');const c=course(id),l=getLesson(c,+si,+li);return `<div><span class="activity-check">✓</span><p>Completed <strong>${esc(l?.title||'a lesson')}</strong><small>${esc(c.title)}</small></p></div>`}).join('')||'<p class="muted-copy">Your completed lessons will appear here. Start with a short lesson today.</p>'}</div></section>`}
  function renderProfile(){header('Profile and settings','Profile and settings');const user=state.user;view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> PREFERENCES</div><h1>Your learning, <em>your way.</em></h1><p>A few preferences can help shape a path that fits your goals.</p></div><section class="settings-card"><div class="settings-heading"><div class="avatar">${esc((user?.name||'L').slice(0,1).toUpperCase())}</div><div><h2>${esc(user?.name||'Learner profile')}</h2><p>${user?`${esc(user.email)} · local profile`:'Guest learner · progress saved in this browser'}</p></div>${user?'<button id="signOut" class="button button-quiet">Sign out</button>':'<a class="button button-secondary" href="#auth">Sign in options →</a>'}</div><label class="form-label">What would you like to learn first?<select id="prefCourse">${courses.map(c=>`<option value="${c.id}" ${state.preferences?.course===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label class="form-label">How much time can you study each week?<select id="prefTime"><option>1–2 hours</option><option>3–5 hours</option><option>6+ hours</option></select></label><label class="form-label">Your experience level<select id="prefLevel"><option>Just getting started</option><option>Some experience</option><option>Comfortable with the basics</option></select></label><button id="savePreferences" class="button button-primary">Save preferences <span>→</span></button></section><section class="settings-note"><span>◈</span><p><strong>${user?'Local profile only.':'Guest mode is on.'}</strong> Your lessons, notes, bookmarks, and quiz checks are saved on this device. These profiles do not provide password authentication or cloud sync.</p></section>`;$('#savePreferences').onclick=()=>{state.preferences={course:$('#prefCourse').value,time:$('#prefTime').value,level:$('#prefLevel').value};save();toast('Preferences saved on this device.')};if(user)$('#signOut').onclick=()=>{state.user=null;save();toast('Signed out of this local profile.');renderProfile()}}
  function renderHelp(){header('About and help','About and help');view.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="eyebrow-dot"></span> A NOTE FROM CODECRAFT</div><h1>Clear paths.<br><em>Room to explore.</em></h1><p>Codecraft is a small, hands-on coding academy designed for curious beginners.</p></div><section class="help-content"><h2>How this learning space works</h2><p>Choose a course and follow its roadmap. Each lesson includes an explanation, runnable example where supported, a knowledge check, and space for your own notes. Mark lessons complete when you feel ready.</p><details><summary>Where is my progress saved?</summary><p>Guest progress is stored in your browser on this device. Clearing site data clears progress. There is no account or cloud sync in this starter release.</p></details><details><summary>Which code can I run?</summary><p>HTML, CSS, and JavaScript run in a sandboxed browser preview. Python, C++, and SQL run through the configured isolated Piston runner when its runtime is installed and code sharing is enabled. If a run fails, Code Studio shows a red diagnostic and suggested fixes.</p></details><details><summary>Can I study without an account?</summary><p>Yes. The learning experience works in guest mode. A device-only learner profile is available from Sign in; password authentication and syncing between devices need a secure backend.</p></details><details><summary>How do I add a course?</summary><p>Course and lesson data lives in content.js. Follow the course object structure and add lessons to the appropriate stage. The interface builds roadmaps, lesson navigation, progress, and bookmarks from that content.</p></details><details><summary>Is the AI tutor available?</summary><p>The platform is designed to work without AI. A secure server-side AI integration can be added later without exposing credentials in the browser.</p></details><h2>Current learning paths</h2><p>HTML, CSS, JavaScript, Python, C++, SQL, and a React introduction. The initial courses include structured lesson content and practice. A first guided project is available for each foundational course.</p></section>`}
  function route(){const h=decodeURIComponent(location.hash.replace(/^#\/?/,''));const parts=h.split('/');if(!h||parts[0]==='home'){renderHome()}else{switch(parts[0]){case'explore':renderExplore();break;case'course':renderCourse(parts[1]);break;case'lesson':renderLesson(parts[1],parts[2],parts[3]);break;case'practice':if(parts[1]==='studio')renderStudio();else if(parts[1])renderProblem(parts[1]);else renderPractice();break;case'projects':parts[1]==='view'?renderProject(Number(parts[2])):renderProjects();break;case'bookmarks':renderBookmarks();break;case'dashboard':renderDashboard();break;case'profile':renderProfile();break;case'auth':renderAuth(parts[1]);break;case'help':renderHelp();break;default:renderHome()}}view.focus({preventScroll:true});const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduceMotion&&view.animate)view.animate([{opacity:.35,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:210,easing:'cubic-bezier(.2,.7,.2,1)'});window.scrollTo({top:0,behavior:reduceMotion?'instant':'smooth'})}
  function setup(){renderSide();document.documentElement.dataset.theme=state.theme||'light';window.addEventListener('hashchange',route);route();$('#themeToggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;save()};$('#addCourse').onclick=()=>setRoute('explore');$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#helpButton').onclick=()=>setRoute('help');$('#globalSearch').addEventListener('input',e=>{if(e.target.value.trim()){searchTerm=e.target.value.trim();setRoute('explore');setTimeout(()=>{const f=$('#courseSearch');if(f){f.value=searchTerm;f.dispatchEvent(new Event('input'))}},20)}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}if(e.key==='Escape')$('#sidebar').classList.remove('open')});$('#modalClose').onclick=()=>$('#modal').close()}
  setup();
})();
